query_expression:
timeseries RequestFailure = sum(dt.service.request.failure_count, default: 0), by: { endpoint.name, dt.entity.service }, interval: 1m
| lookup [fetch dt.entity.service], sourceField:dt.entity.service, lookupField:id, fields:{service_name = entity.name}
| filter service_name ~ "SERVICE-MUDAR" AND endpoint.name == "/downloadservice/file.crypt.download.filesystem"

